<?php require_once '../../includes/auth.php';require_once '../../config/conexion.php';$titulo='Tablero UCIN';require '../../includes/header.php';$rows=$pdo->query('SELECT * FROM v_tablero_ucin ORDER BY numero_espacio')->fetchAll();$total=count($rows);$ocup=count(array_filter($rows,fn($r)=>$r['estado_espacio']==='Ocupada'));$disp=count(array_filter($rows,fn($r)=>$r['estado_espacio']==='Disponible'));$mant=count(array_filter($rows,fn($r)=>$r['estado_espacio']==='En Mantenimiento/Limpieza'));$pct=$total?round($ocup/$total*100,1):0; ?><h1>Tablero de ocupación UCIN</h1><div class="kpis"><div class="kpi"><span>Total espacios</span><b><?= $total ?></b></div><div class="kpi ocupado"><span>Ocupados</span><b><?= $ocup ?></b></div><div class="kpi disponible"><span>Disponibles</span><b><?= $disp ?></b></div><div class="kpi mantenimiento"><span>Mantenimiento</span><b><?= $mant ?></b></div><div class="kpi"><span>Ocupación</span><b><?= $pct ?>%</b></div></div><div class="barra"><span style="width:<?= $pct ?>%"></span></div><div class="acciones"><label>Zona <select id="fZona"><option value="">Todas</option><option>Área de Cuidados Intensivos</option><option>Área de Cuidados Intermedios</option><option>Crecimiento y Aislamiento</option></select></label><label>Equipo <select id="fTipo"><option value="">Todos</option><option value="incubadora">Incubadoras</option><option value="cuna">Cunas</option></select></label><span id="actualizado">Actualizado: <?= date('H:i:s') ?></span></div><div id="espacios" class="tarjetas"><?php foreach($rows as $r): ?><article class="espacio <?= $r['estado_espacio']==='Ocupada'?'es-ocupada':($r['estado_espacio']==='Disponible'?'es-disponible':'es-mantenimiento') ?>" data-zona="<?= h($r['zona_ucin']) ?>" data-tipo="<?= str_contains($r['tipo_equipo'],'Incubadora')?'incubadora':'cuna' ?>"><div class="espacio-head"><b><?= h($r['numero_espacio']) ?></b><span><?= h($r['estado_espacio']) ?></span></div><p><?= h($r['tipo_equipo']) ?></p><?php if($r['id_neonato']): ?><h3><?= h($r['nombre_neonato']) ?></h3><p><?= h($r['exp_neonato']) ?> · <?= (int)$r['semanas_gestacion'] ?> semanas</p><p>Peso: <?= (int)$r['peso_actual_gramos'] ?> g · <?= (int)$r['dias_estancia'] ?> días</p><p>Estado clínico: <b><?= h($r['estado_clinico']) ?></b></p><details><summary>Más información</summary><p>Madre: <?= h($r['nombre_madre']) ?></p><p>Médico: <?= h($r['medico_tratante']) ?></p><p>Visitas: <?= h($r['visitas']) ?></p><p>Estudio: <?= h($r['estudios_proximos']) ?> <?= h($r['fecha_estudio_programado']) ?></p></details><?php else: ?><p><?= h($r['zona_ucin']) ?></p><?php endif; ?></article><?php endforeach; ?></div><script src="assets/tablero.js"></script><?php require '../../includes/footer.php'; ?>
